ee:message.ee:set-payload:
%dw 2.0
output application/json
var reconciledTotal = sizeOf(vars.pendingReconcileList default [])
---
{
    success: true,
    reconciledCount: reconciledTotal,
    status: "RECONCILIATION_COMPLETED",
    message: "Reconciliation cycle executed. Processed " ++ (reconciledTotal as String) ++ " quarantined events.",
    timestamp: (now() >> "UTC") as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}
